Bash(NODE_ENV=development PINECONE_INDEX_NAME=glowlytics-guidelines node -e "
require\('dotenv'\).config\(\);
process.env.PINECONE_INDEX_NAME = 'glowlytics-guidelines';
const OpenAI = require\('openai'\);
const { Pinecone } = require\('@pinecone-database/pinecone'\);
const openai = new OpenAI\({ apiKey: process.env.OPENAI_API_KEY }\);
const pc = new Pinecone\({ apiKey: process.env.PINECONE_API_KEY }\);
const index = pc.index\('glowlytics-guidelines'\);
const { GUIDELINE_CHUNKS } = require\('./rag'\);

\(async \(\) => {
  const chunk = GUIDELINE_CHUNKS[0];
  const resp = await openai.embeddings.create\({ model: 'text-embedding-3-small', input: chunk.text }\);
  const vector = resp.data[0].embedding;
  console.log\('Embedding length:', vector.length\);

  const records = [{ id: chunk.id, values: vector, metadata: { text: chunk.text, category: chunk.category } }];
  await index.upsert\(records\);
  console.log\('Single upsert OK'\);

  // Now do all 19
  const allEmbeddings = await Promise.all\(GUIDELINE_CHUNKS.map\(c =>
    openai.embeddings.create\({ model: 'text-embedding-3-small', input: c.text }\).then\(r => r.data[0].embedding\)
  \)\);
  const allRecords = GUIDELINE_CHUNKS.map\(\(c, i\) => \({
    id: c.id, values: allEmbeddings[i], metadata: { text: c.text, category: c.category }
  }\)\);
  await index.upsert\(allRecords\);
  console.log\('All 19 seeded successfully'\);
}\)\(\).catch\(e => console.error\('Error:', e.message\)\);
" 2>&1)
